struct statfs fs_stats;
int fd = open("/tmp", O_RDONLY); // Target filesystem via descriptor

if (fd < 0) {
    // EBADF likely if open failed
}

// Populate fs_stats with filesystem metadata
int result = fstatfs(fd, &fs_stats);

if (result == 0) {
    // Success: Access statistics
    long block_size = fs_stats.f_bsize;
    unsigned long available = fs_stats.f_bavail;
} else {
    // Error handling (EFAULT, EBADF)
}

close(fd);
